// A connected campus experience, using the shared app context and request lifecycle.
const campusWidgetLabels={schedule:'Ближайшие занятия',plan:'Мой план',progress:'Учебный прогресс',events:'События клубов',news:'Новости',requests:'Заявки',meetings:'Консультации',quick:'Быстрые действия'};
const campusStatusLabels={todo:'Не начал',doing:'В работе',done:'Готово'};
const campusKinds={homework:'Домашнее задание',task:'Личная задача',news:'Срок объявления',exam:'Сессия',event:'Встреча клуба',consultation:'Консультация'};
function campusSubjectButton(subject,group=''){return `<button class="campus-subject-link" data-campus-subject="${esc(subject)}" data-campus-group="${esc(group||'')}">${esc(subject)}</button>`;}
function campusRoomButton(room){return `<button class="campus-inline-link" data-campus-place="${esc(room)}">${icon('pin','icon-sm')} ${esc(room)}</button>`;}
function campusOverview(){return state.data.campusOverview||{};}
function campusPlanData(){return state.view==='plan'?state.data.campusPlan||{items:[]}:campusOverview().plan||{items:[]};}
function campusEventsData(){return state.data.campusEvents||campusOverview().events||{events:[],clubs:[]};}
function campusConsultData(){return state.data.campusConsultations||campusOverview().consultations||{slots:[],staff:[],groups:[]};}
function campusLocalTime(value){if(!value)return '';return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(value)).replace(' ','T');}
function campusTime(value){return dateFmt(value,{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit'});}
function campusField(label,name,value='',type='text',extra=''){return `<div class="field"><label for="campus-${name}">${esc(label)}</label><input id="campus-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function campusSelect(label,name,items,value='',extra=''){return `<div class="field"><label for="campus-${name}">${esc(label)}</label><select id="campus-${name}" name="${name}" ${extra}>${items.map(([id,title])=>`<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(title)}</option>`).join('')}</select></div>`;}
function campusEventCover(event,small=false){return `<div class="campus-event-cover cover-${esc(event.cover||'orbit')} ${small?'is-small':''}" aria-hidden="true"><span class="campus-cover-orbit"></span><span class="campus-cover-ring"></span><span class="campus-cover-symbol">${icon(event.cover==='nature'?'sun':event.cover==='sport'?'award':event.cover==='studio'?'palette':'spark')}</span><span class="campus-cover-caption">ВМЕСТЕ В КАМПОРИИ</span></div>`;}
function campusPlanRows(items,small=false){return items.length?items.map(item=>`<article class="campus-plan-row ${item.status==='done'?'is-done':''} ${item.overdue?'is-overdue':''}"><span class="campus-plan-marker">${icon(item.status==='done'?'check':item.kind==='task'?'edit':item.kind==='event'?'users':'calendar','icon-sm')}</span><div class="campus-plan-copy"><span class="campus-kicker">${esc(campusKinds[item.kind]||'Задача')}${item.overdue?' · Срок прошёл':''}</span><button class="campus-plan-title" data-campus-plan-open="${esc(item.key)}">${esc(item.title)}</button><div>${item.subject?campusSubjectButton(item.subject,item.groupId||state.user.groupId):''}<span class="muted">${esc(shortDate(item.date))}${item.startsAt?' · '+esc(campusTime(item.startsAt)):''}</span></div></div><select class="campus-status-select" data-campus-progress="${esc(item.key)}" aria-label="Личный статус: ${esc(item.title)}">${Object.entries(campusStatusLabels).map(([value,label])=>`<option value="${value}" ${item.status===value?'selected':''}>${label}</option>`).join('')}</select>${!small&&item.kind==='task'?`<button class="icon-btn" data-campus-task-remove="${esc(item.id)}" aria-label="Удалить личную задачу">${icon('close','icon-sm')}</button>`:''}</article>`).join(''):emptyState('Здесь пока свободно','Можно добавить личную задачу или выбрать другой период.','check');}
function campusUpcomingPlan(limit=4){const today=campusToday();return arr(campusOverview().plan?.items).filter(x=>x.status!=='done'&&x.date<=dateAdd(today,6)).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,limit);}
function campusWidget(id){
 const dashboard=state.data.dashboard||{},lessons=arr(dashboard.today).filter(x=>!calendarUnavailable(x)),events=arr(campusOverview().events?.events).filter(x=>x.status==='published'&&Date.parse(x.endsAt)>Date.now()),meetings=arr(campusOverview().consultations?.slots).filter(x=>(x.mine||x.canManage&&x.booking)&&x.status==='active'),news=arr(dashboard.news||state.data.news);
 const link=(view,label='Все')=>`<button class="text-link" data-view="${view}">${label} →</button>`;
 let body='',action='';
 if(id==='schedule'){action=link('schedule','Расписание');body=lessons.length?`<div class="today-list">${lessons.slice(0,3).map((x,i)=>lessonRow(x,i,state.user.role==='admin')).join('')}</div>`:emptyState('Свободный день','Выберите дату в расписании.','calendar');}
 if(id==='plan'){action=link('plan','Открыть');body=campusPlanRows(campusUpcomingPlan(),true);}
 if(id==='progress'){action=link('grades','Подробнее');body=`<div class="campus-metrics"><div><strong>${esc(dashboard.gradeAverage??'—')}</strong><span>Средний балл</span></div><div><strong>${dashboard.attendance==null?'—':esc(dashboard.attendance)+'%'}</strong><span>Посещаемость</span></div></div><button class="btn btn-light btn-small" data-campus-action="forecast">${icon('chart','icon-sm')} Что будет, если…</button>`;}
 if(id==='events'){action=link('events','Афиша');body=events.length?events.slice(0,2).map(e=>`<button class="campus-mini-event" data-campus-event="${esc(e.id)}">${campusEventCover(e,true)}<span><small>${esc(shortDate(e.startsAt))} · ${esc(e.club)}</small><strong>${esc(e.title)}</strong><span>${e.isGoing?'Вы записаны':esc(quantity(e.remaining,['место','места','мест']))}</span></span>${icon('chevron','icon-sm')}</button>`).join(''):emptyState('События готовятся','Новые встречи появятся в афише.','spark');}
 if(id==='news'){action=link('news');body=news.length?news.slice(0,3).map(n=>`<article class="campus-mini-news"><span class="feed-icon">${icon(n.pinned?'pin':'news')}</span><div><strong>${esc(n.title)}</strong><p>${esc(n.body)}</p><small>${esc(n.author)} · ${esc(shortDate(n.createdAt))}</small></div></article>`).join(''):emptyState('Пока тихо','Здесь появятся объявления университета.','news');}
 if(id==='requests'){action=link('requests','История');const count=isStudent()?dashboard.pendingRequests:arr(state.data.staff?.requests).filter(x=>['submitted','in_review'].includes(x.status)).length;body=`<div class="campus-metrics"><div><strong>${Number(count)||0}</strong><span>${isStudent()?'Ожидают ответа':'Требуют внимания'}</span></div></div>${isStudent()?'<button class="btn btn-light" data-action="new-request">Подать заявку</button>':''}`;}
 if(id==='meetings'){action=link('consultations','Все');body=meetings.length?meetings.slice(0,3).map(s=>`<button class="campus-meeting-mini" data-view="consultations">${icon('clock')}<span><strong>${esc(s.mine?s.owner:s.booking?.student||'Встреча')}</strong><small>${esc(shortDate(s.startsAt))} · ${esc(campusTime(s.startsAt))}</small></span></button>`).join(''):emptyState('Встреч пока нет',isStudent()?'Выберите время у преподавателя или в учебном офисе.':'Откройте свободное время для студентов.','clock');}
 if(id==='quick'){body=`<div class="quick-actions">${isStudent()?'<button class="quick-action" data-action="new-request">'+icon('file')+' Подать заявку '+icon('chevron')+'</button>':'<button class="quick-action" data-action="new-news">'+icon('news')+' Написать объявление '+icon('chevron')+'</button>'}<button class="quick-action" data-view="consultations">${icon('clock')} Консультации ${icon('chevron')}</button><button class="quick-action" data-view="resources">${icon('folder')} Материалы ${icon('chevron')}</button><button class="quick-action" data-view="campus">${icon('pin')} Найти аудиторию ${icon('chevron')}</button></div>`;}
 return `<section class="card campus-widget widget-${id}" data-campus-widget="${id}"><div class="section-title"><h2>${esc(id==='schedule'&&!dashboard.todayIsNextDay?'Занятия на сегодня':campusWidgetLabels[id])}</h2>${action}</div>${body}</section>`;
}
function renderHome(){
 const preferences=campusOverview().preferences||{widgets:['schedule','plan','news','events','quick']},changes=arr(state.data.dashboard?.today).filter(x=>x.changed);
 return `${pageHeader('Ваше пространство',`Здравствуйте, ${esc(firstName(state.user.name))}!`,'Ваш ритм. Ваши планы. Всё нужное рядом.',`<button class="btn btn-light" data-campus-action="preferences">${icon('settings')} Настроить главную</button>`)}<section class="campus-welcome"><div><span class="eyebrow">${esc(state.user.group||roleName(state.user.role))} · КАМПОРИЯ</span><h2>Соберите день<br>по-своему.</h2><p>${isStudent()?'От первой пары до встречи с клубом — каждый шаг уже под рукой.':'Учебные задачи, встречи и университетская команда — в одном пространстве.'}</p></div><div class="campus-welcome-art" aria-hidden="true"><span></span><span></span><span></span>${icon('spark')}</div></section>${changes.length?`<div class="campus-important" role="status">${icon('alert')}<span>Есть изменения в расписании: ${changes.slice(0,2).map(x=>esc(x.subject)).join(', ')}.</span><button class="text-link" data-view="schedule">Проверить →</button></div>`:''}<div class="campus-home-grid ${preferences.compact?'is-compact':''}">${arr(preferences.widgets).map(campusWidget).join('')}</div>`;
}
function renderCampusPlan(){
 const data=state.data.campusPlan||{items:[]},today=campusToday(),filter=state.campusPlanFilter||'week';let items=arr(data.items);
 if(filter==='today')items=items.filter(x=>x.date===today);if(filter==='week')items=items.filter(x=>x.date>=today&&x.date<=dateAdd(today,6));if(filter==='overdue')items=items.filter(x=>x.overdue);if(filter==='done')items=items.filter(x=>x.status==='done');if(state.campusPlanSubject)items=items.filter(x=>x.subject===state.campusPlanSubject);
 const subjects=[...new Set(arr(data.items).map(x=>x.subject).filter(Boolean))];
 return `${pageHeader('Один план для всего','Мой учебный ритм','Учебные сроки и личные задачи. Отметки прогресса видны только вам.',`<button class="btn btn-primary" data-campus-action="new-task">${icon('plus')} Личная задача</button>`)}<div class="campus-plan-summary"><div><strong>${arr(data.items).filter(x=>x.date===today&&x.status!=='done').length}</strong><span>На сегодня</span></div><div><strong>${arr(data.items).filter(x=>x.overdue).length}</strong><span>Проверить сроки</span></div><div><strong>${arr(data.items).filter(x=>x.status==='done').length}</strong><span>Отмечено готовым</span></div><span class="campus-summary-art" aria-hidden="true">${icon('check')}</span></div><div class="campus-toolbar"><div class="tabs campus-scroll-tabs">${[['today','Сегодня'],['week','7 дней'],['overdue','Просрочено'],['all','Все задачи'],['done','Готово']].map(([id,title])=>`<button class="tab ${filter===id?'active':''}" data-campus-plan-filter="${id}">${title}</button>`).join('')}</div><select id="campus-plan-subject" aria-label="Фильтр по предмету"><option value="">Все предметы</option>${subjects.map(s=>`<option ${state.campusPlanSubject===s?'selected':''}>${esc(s)}</option>`).join('')}</select></div><section class="card campus-plan-list">${campusPlanRows(items)}</section><p class="campus-footnote">«Готово» — ваша личная отметка. Принятие работы и оценки преподавателя отражаются отдельно в журнале.</p>`;
}
function campusEventCard(e){const past=Date.parse(e.startsAt)<=Date.now(),cancelled=e.status==='cancelled';return `<article class="card campus-event-card ${cancelled?'is-cancelled':''}">${campusEventCover(e)}<div class="campus-event-content"><div class="campus-event-meta"><span>${esc(e.club)}</span><span>${e.audience==='members'?'Для участников клуба':'Открытая встреча'}</span></div><h2><button data-campus-event="${esc(e.id)}">${esc(e.title)}</button></h2><p>${esc(e.body)}</p><div class="campus-event-info"><span>${icon('calendar','icon-sm')} ${esc(shortDate(e.startsAt))} · ${esc(campusTime(e.startsAt))}</span>${campusRoomButton(e.place)}</div><div class="campus-capacity"><span>${cancelled?'Событие отменено':e.isGoing?'Вы в списке участников':past?'Запись завершена':e.remaining?'Осталось '+e.remaining+' из '+e.capacity+' мест':'Мест больше нет'}</span><div><i style="width:${Math.min(100,e.participants/e.capacity*100)}%"></i></div></div><div class="campus-event-actions">${cancelled?'<span class="tag">Отменено</span>':e.isGoing?`<button class="btn btn-light" data-campus-event-leave="${esc(e.id)}">${icon('check','icon-sm')} Вы идёте</button>`:`<button class="btn btn-primary" data-campus-event-join="${esc(e.id)}" ${past||!e.remaining?'disabled':''}>Пойду ${icon('arrow','icon-sm')}</button>`}<button class="btn btn-ghost" data-campus-event="${esc(e.id)}">Подробнее</button>${e.canManage?`<button class="icon-btn" data-campus-event-edit="${esc(e.id)}" ${cancelled||past?'disabled':''} aria-label="Изменить событие">${icon('edit','icon-sm')}</button>`:''}</div></div></article>`;}
function renderCampusEvents(){
 const data=campusEventsData(),filter=state.campusEventFilter||'all';let events=arr(data.events).filter(e=>filter!=='mine'||e.isGoing);if(state.campusEventClub)events=events.filter(e=>e.clubId===state.campusEventClub);if(state.campusEventDate)events=events.filter(e=>campusLocalTime(e.startsAt).slice(0,10)===state.campusEventDate);
 return `${pageHeader('За пределами расписания','Афиша кампуса','Встречи, проекты и люди, с которыми интересно быть вместе.',arr(data.clubs).some(c=>c.canManage)?`<button class="btn btn-primary" data-campus-action="new-event">${icon('plus')} Создать событие</button>`:'')}<div class="campus-toolbar"><div class="tabs"><button class="tab ${filter==='all'?'active':''}" data-campus-event-filter="all">Все события</button><button class="tab ${filter==='mine'?'active':''}" data-campus-event-filter="mine">Я иду</button></div><div class="campus-toolbar-fields"><select id="campus-event-club" aria-label="Сообщество"><option value="">Все сообщества</option>${arr(data.clubs).map(c=>`<option value="${esc(c.id)}" ${state.campusEventClub===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><input id="campus-event-date" type="date" aria-label="Дата события" value="${esc(state.campusEventDate||'')}"></div></div>${events.length?`<div class="campus-events-grid">${events.map(campusEventCard).join('')}</div>`:`<div class="card card-pad">${emptyState('Встреч пока нет','Попробуйте другую дату или посмотрите события других клубов.','spark')}</div>`}`;
}
function renderCampusConsultations(){
 const data=campusConsultData(),mine=state.campusConsultFilter==='mine',staff=state.campusConsultStaff||'';
 const slots=arr(data.slots).filter(s=>(!staff||s.ownerId===staff)&&(!mine||s.mine||s.ownerId===state.user.id)&&Date.parse(s.endsAt)>Date.now());
 const grouped=new Map();for(const s of slots){const day=campusLocalTime(s.startsAt).slice(0,10);if(!grouped.has(day))grouped.set(day,[]);grouped.get(day).push(s);}
 return `${pageHeader('Время для разговора','Консультации','Выберите свободное окно у преподавателя или в учебном офисе.',data.canCreate?`<button class="btn btn-primary" data-campus-action="new-slot">${icon('plus')} Открыть время</button>`:'')}<div class="campus-toolbar"><div class="tabs"><button class="tab ${!mine?'active':''}" data-campus-consult-filter="all">Все окна</button><button class="tab ${mine?'active':''}" data-campus-consult-filter="mine">Мои встречи</button></div><select id="campus-consult-staff" aria-label="Сотрудник"><option value="">Все сотрудники</option>${arr(data.staff).map(s=>`<option value="${esc(s.id)}" ${staff===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><p class="campus-footnote">Время указано по Москве. При записи проверяются занятия и другие консультации.</p>${slots.length?[...grouped].map(([day,values])=>`<section class="campus-consult-day"><div class="section-title"><h2>${esc(dateFmt(day,{weekday:'long',day:'numeric',month:'long'}))}</h2></div><div class="campus-slots-grid">${values.map(s=>`<article class="card campus-slot ${s.mine?'is-mine':''}"><div class="campus-slot-time">${esc(campusTime(s.startsAt))}<span>— ${esc(campusTime(s.endsAt))}</span><span class="tag">${s.format==='online'?'Онлайн':'В кампусе'}</span></div><h3>${esc(s.owner)}</h3><p>${esc(s.group||'Для всех учебных групп')}</p><div class="campus-slot-place">${s.format==='offline'?campusRoomButton(s.place):campusOnlinePlace(s.place)}</div>${s.status==='cancelled'?'<p class="campus-cancelled-text">Приём отменён</p>':s.booking?`<div class="campus-booking"><strong>${s.mine?'Вы записаны':esc(s.booking.student)}</strong><p>${esc(s.booking.topic)}</p><button class="text-link" data-campus-booking-cancel="${esc(s.booking.id)}">Отменить запись</button></div>`:s.available&&isStudent()?`<button class="btn btn-primary" data-campus-book="${esc(s.id)}">Выбрать это время</button>`:`<span class="tag">${s.available?'Открыто для записи':'Время занято'}</span>`}${s.canManage&&s.status==='active'?`<button class="campus-slot-cancel" data-campus-slot-cancel="${esc(s.id)}">Закрыть приём</button>`:''}</article>`).join('')}</div></section>`).join(''):`<div class="card card-pad">${emptyState('Подходящих окон пока нет',data.canCreate?'Откройте время, когда готовы принять студентов.':'Можно выбрать другого сотрудника или заглянуть позже.','clock')}</div>`}`;
}
function renderCampusSubject(){const hub=state.data.campusHub;if(!hub)return '';const lessons=arr(hub.lessons).filter(x=>!calendarUnavailable(x)&&Date.parse(x.date+'T'+x.endTime+':00+03:00')>Date.now()),hw=arr(hub.homework);return `${pageHeader('Всё по одному предмету',esc(hub.subject),`${esc(hub.group||'')} · ближайшие занятия, задания и материалы`,`<button class="btn btn-ghost" data-campus-action="subject-back">${icon('arrowLeft')} Назад</button><button class="btn btn-light" data-campus-action="forecast">${icon('chart')} ${isStudent()?'Прогноз':'Правила оценивания'}</button>`)}<div class="campus-subject-hero"><div><span class="eyebrow">СЛЕДУЮЩАЯ ВСТРЕЧА</span><h2>${lessons[0]?esc(dateFmt(lessons[0].date,{weekday:'long',day:'numeric',month:'long'})):'Расписание готовится'}</h2><p>${lessons[0]?esc(lessons[0].startTime)+'–'+esc(lessons[0].endTime)+' · '+esc(lessons[0].type):'Ближайшая пара пока не назначена'}</p></div><div class="campus-subject-teachers">${arr(hub.teachers).map(t=>`<div><span class="avatar">${esc(initials(t.name))}</span><div>${personButton(t.id,t.name,'teacher')}${isStudent()&&t.canBook?`<button class="text-link" data-campus-consult-staff="${esc(t.id)}">Консультация →</button>`:`<button class="text-link" data-person-schedule="${esc(t.id)}">Расписание →</button>`}</div></div>`).join('')}</div></div><div class="campus-subject-grid"><section class="card campus-widget"><div class="section-title"><h2>К следующей паре</h2><button class="text-link" data-campus-hub-homework>Все ДЗ →</button></div>${hw.length?hw.slice(0,4).map(h=>`<article class="campus-hub-homework"><span class="tag">До ${esc(shortDate(h.dueDate))}</span><h3>${esc(h.title)}</h3><p>${esc(h.body)}</p><small>${esc(h.author||'Преподаватель')}</small></article>`).join(''):emptyState('Новых заданий пока нет','Можно повторить материалы предмета.','check')}</section><section class="card campus-widget"><div class="section-title"><h2>Материалы</h2><button class="text-link" data-campus-hub-materials>Все →</button></div>${arr(hub.resources).slice(0,5).map(r=>`<button class="campus-hub-resource" data-campus-hub-resource="${esc(r.id)}">${icon('file')}<span><strong>${esc(r.title)}</strong><small>${r.kind==='teacher'?'Преподаватель · '+esc(r.author):'Общее пособие'} · ${esc(r.type)}</small></span>${icon('chevron','icon-sm')}</button>`).join('')||emptyState('Материалы готовятся','Публикации появятся здесь после добавления.','folder')}</section><section class="card campus-widget"><div class="section-title"><h2>Ближайшие занятия</h2></div>${lessons.slice(0,4).map((l,i)=>`<div class="campus-subject-lesson"><button class="campus-lesson-date text-link" data-campus-lesson-date="${esc(l.date)}">${esc(dateFmt(l.date,{weekday:'short',day:'numeric',month:'short'}))} →</button>${lessonRow(l,i,state.user.role==='admin')}</div>`).join('')||emptyState('Нет ближайших занятий','Проверьте полное расписание.','calendar')}</section><section class="card campus-widget"><div class="section-title"><h2>${isStudent()?'Мои результаты':'Работа с группой'}</h2></div>${isStudent()?arr(hub.grades).length?arr(hub.grades).map(g=>`<div class="campus-grade-row"><span><strong>${esc(({grade:'Текущая оценка',exam:'Экзамен',credit:'Зачёт'}[g.kind]))}</strong><small>${esc(shortDate(g.recordedAt))} · ${esc(g.note||'')}</small></span>${g.kind==='credit'?esc(g.value>=3?'Зачтено':'Не зачтено'):gradeValue(g.value)}</div>`).join(''):emptyState('Оценок ещё нет','Результаты появятся после заполнения журнала.','grades'):`<p class="muted">${esc(hub.group)} · ваши задания, материалы и условия оценивания.</p><div class="campus-action-stack"><button class="btn btn-light" data-view="staff">${icon('grades')} ${state.user.role==='teacher'?'Открыть журнал':'Рабочее место'}</button></div>`}</section></div>`;}

function campusMapPlaces(){const data=state.data.campusMap||{places:[]};return arr(data.places).filter(p=>(!state.campusBuilding||p.building===state.campusBuilding)&&(!state.campusMapSearch||(p.room+' '+p.title).toLowerCase().includes(state.campusMapSearch.toLowerCase())));}
function campusMapDetail(){const data=state.data.campusMap||{},place=arr(data.places).find(p=>p.room===state.campusPlace),building=arr(data.buildings).find(b=>b.id===place?.building);return place?`<span class="eyebrow">${esc(building?.name)} · ${place.floor} этаж</span><h2>${esc(place.title)}</h2><div class="campus-floor-plan" aria-label="Условная схема этажа"><span class="campus-floor-corridor">КОРИДОР · ЭТАЖ ${place.floor}</span>${[0,1,2,3,4,5].map((n)=>`<span class="${n===2?'is-target':''}">${n===2?esc(place.room):n===4?'Лестница':'Кабинет'}</span>`).join('')}</div><h3>Как пройти</h3><p>${esc(place.directions)}</p>${state.user.role==='admin'?'<button class="btn btn-light" data-campus-action="edit-place">Изменить описание</button>':''}`:`<span class="eyebrow">ОРИЕНТИРЫ КАМПУСА</span><h2>${state.campusPlace?esc(state.campusPlace):'Куда направимся?'}</h2><p>${state.campusPlace?'Для этого места схема ещё не добавлена. Уточните корпус у преподавателя или в учебном офисе.':'Выберите корпус и найдите аудиторию, библиотеку или место встречи.'}</p>${state.user.role==='admin'?'<button class="btn btn-light" data-campus-action="edit-place">Добавить место на схему</button>':''}`;}
function renderCampusMap(){const data=state.data.campusMap||{buildings:[],places:[]};return `${pageHeader('Университет ближе','Навигатор кампуса','Аудитории, места встреч и студенческие сервисы.',state.user.role==='admin'?'<button class="btn btn-light" data-campus-action="new-place">'+icon('plus')+' Добавить место</button>':'')}<div class="campus-map-layout ${state.campusPlace?'has-selection':''}"><section class="card campus-map-main"><div class="campus-map-head"><span class="tag">Демонстрационный кампус</span><span class="muted">Схема, не масштабный план</span></div><svg class="campus-map-svg" viewBox="0 0 540 340" role="img" aria-label="Учебный корпус А, лабораторный корпус Б и студенческий центр"><defs><pattern id="campus-map-grid" width="25" height="25" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1" fill="currentColor" opacity=".12"/></pattern></defs><rect width="540" height="340" rx="20" fill="url(#campus-map-grid)"/><path d="M95 104V260H430V236M285 104V260" fill="none" stroke="currentColor" stroke-width="23" opacity=".05"/><path d="M95 104V260H430V236M285 104V260" fill="none" stroke="currentColor" stroke-width="2" stroke-dasharray="5 7" opacity=".22"/><g fill="currentColor" opacity=".12"><circle cx="200" cy="187" r="22"/><circle cx="330" cy="210" r="15"/><circle cx="478" cy="82" r="23"/><circle cx="53" cy="220" r="17"/></g>${arr(data.buildings).map(b=>`<g class="campus-map-building ${(state.campusBuilding||arr(data.places).find(p=>p.room===state.campusPlace)?.building)===b.id?'is-active':''}"><rect x="${b.x-48}" y="${b.y-37}" width="96" height="74" rx="15"/><text x="${b.x}" y="${b.y+8}" text-anchor="middle">${b.id==='A'?'А':b.id==='B'?'Б':'В'}</text><text class="campus-map-label" x="${b.x}" y="${b.y+58}" text-anchor="middle">${esc(b.id==='A'?'Учебный корпус':b.id==='B'?'Лаборатории':'Студцентр')}</text></g>`).join('')}</svg><div class="campus-building-buttons"><button class="btn ${!state.campusBuilding?'btn-primary':'btn-light'}" data-campus-building="">Все</button>${arr(data.buildings).map(b=>`<button class="btn ${state.campusBuilding===b.id?'btn-primary':'btn-light'}" data-campus-building="${b.id}">${esc(b.name)}</button>`).join('')}</div><label class="campus-map-search">${icon('search')}<input id="campus-map-search" placeholder="Аудитория или место" aria-label="Поиск на схеме" value="${esc(state.campusMapSearch||'')}"></label><div id="campus-map-results" class="campus-map-results">${campusMapResults()}</div></section><aside class="card campus-map-detail" id="campus-map-detail">${campusMapDetail()}</aside></div><p class="campus-footnote">Кампус и маршруты вымышлены. Текстовые ориентиры доступны без анимации.</p>`;}
function campusMapResults(){return campusMapPlaces().map(p=>`<button data-campus-map-room="${esc(p.room)}" class="${state.campusPlace===p.room?'is-active':''}">${icon('pin','icon-sm')}<span><strong>${esc(p.title)}</strong><small>${p.building==='A'?'Корпус А':p.building==='B'?'Корпус Б':'Студцентр'} · ${p.floor} этаж</small></span>${icon('chevron','icon-sm')}</button>`).join('')||'<p class="muted">Такого места пока нет на схеме.</p>';}
function renderCampusPage(){return ({plan:renderCampusPlan,events:renderCampusEvents,consultations:renderCampusConsultations,subject:renderCampusSubject,campus:renderCampusMap}[state.view])();}
function campusRuleKey(groupId,subject){return encodeURIComponent(groupId)+'|'+encodeURIComponent(subject);}
function campusForecastSelection(){const data=state.modal?.forecast||{},options=arr(data.options),key=state.modal?.ruleKey||campusRuleKey(options[0]?.groupId||'',options[0]?.subject||''),[groupPart,subjectPart]=key.split('|'),groupId=decodeURIComponent(groupPart||''),subject=decodeURIComponent(subjectPart||'');return {data,key,groupId,subject,rule:arr(data.rules).find(x=>x.groupId===groupId&&x.subject===subject),grades:arr(data.grades).filter(x=>x.subject===subject&&x.kind!=='credit')};}
function campusForecastResult(){const {rule,grades}=campusForecastSelection();if(!rule)return '<div class="campus-forecast-empty">'+emptyState('Правила ещё не опубликованы','Преподаватель задаст вес текущих результатов и будущей работы. После этого появится прогноз.','chart')+'</div>';if(!grades.length)return '<div class="campus-forecast-empty">'+emptyState('Нужны текущие оценки','Для прогноза должна быть хотя бы одна оценка по этому предмету.','grades')+'</div>';const average=grades.reduce((n,g)=>n+Number(g.value),0)/grades.length,value=Number(state.modal.forecastValue||4),target=Number(state.modal.forecastTarget||4.5),result=average*rule.currentWeight/100+value*rule.futureWeight/100,needed=(target-average*rule.currentWeight/100)*100/rule.futureWeight;return `<div class="campus-forecast-score"><span>Прогнозный средневзвешенный балл</span><strong>${result.toFixed(2)}</strong><div><span>Сейчас ${average.toFixed(2)}</span>${icon('arrow')}<span>С будущей работой ${value.toFixed(1)}</span></div><div class="campus-forecast-track"><i style="width:${Math.max(0,Math.min(100,(result-2)/3*100))}%"></i></div></div><p class="campus-forecast-explain">Для цели ${target.toFixed(1)} ${needed>5?'этой работы недостаточно: даже 5,0 не даст нужный средневзвешенный балл.':needed<=2?'достаточно результата 2,0 или выше.':'на будущей работе понадобится не менее '+(Math.ceil((needed-1e-9)*10)/10).toFixed(1)+'.'}</p>`;}
function renderCampusModal(modal){
 if(!String(modal.type).startsWith('campus-'))return '';
 if(modal.type==='campus-task')return extModalShell(modal.task?'Изменить личную задачу':'Добавить личную задачу','Эту запись и её прогресс видите только вы.',`<form id="campus-task-form">${campusField('Что сделать','title',modal.task?.title||'', 'text','required maxlength="140"')}${campusField('Предмет или категория (необязательно)','subject',modal.task?.subject||'', 'text','maxlength="120"')}${campusField('Срок','dueDate',modal.task?.date||campusToday(),'date','required')}${extModalActions('Добавить в план')}</form>`,'Личный план');
 if(modal.type==='campus-confirm')return extModalShell(modal.title,modal.description,`<form id="campus-confirm-form"><div class="settings-note">${icon('info')}<span>${esc(modal.note||'Изменение сохранится в системе.')}</span></div>${extModalActions(modal.label||'Подтвердить',true)}</form>`,'Подтверждение');
 if(modal.type==='campus-preferences'){const prefs=modal.preferences,order=modal.order;return extModalShell('Ваша главная','Выберите карточки и расположите их так, как удобно вам.',`<form id="campus-preferences-form"><div class="campus-preference-list">${order.map((id,i)=>`<div class="campus-preference-row" draggable="true" data-campus-widget-drag="${i}"><span class="campus-drag-handle" aria-hidden="true">⠿</span><label><input type="checkbox" name="widgets" value="${id}" ${modal.selected.includes(id)?'checked':''}>${esc(campusWidgetLabels[id])}</label><div><button class="icon-btn" type="button" data-campus-widget-move="${i}" data-direction="-1" aria-label="Поднять ${esc(campusWidgetLabels[id])}" ${i===0?'disabled':''}>↑</button><button class="icon-btn" type="button" data-campus-widget-move="${i}" data-direction="1" aria-label="Опустить ${esc(campusWidgetLabels[id])}" ${i===order.length-1?'disabled':''}>↓</button></div></div>`).join('')}</div><label class="campus-check-label"><input type="checkbox" name="compact" ${prefs.compact?'checked':''}>Компактные карточки</label><p class="campus-footnote">Срочные изменения расписания показываются над карточками независимо от этого выбора.</p>${extModalActions('Сохранить главную')}</form>`,'Персонализация');}
 if(modal.type==='campus-event-form'){
  const data=campusEventsData(),event=modal.event||{},clubs=arr(data.clubs).filter(x=>x.canManage),day=dateAdd(campusToday(),3);
  return extModalShell(event.id?'Изменить событие':'Новое событие клуба','Встреча появится в афише, а участники смогут записаться.',`<form id="campus-event-form">${event.id?'':campusSelect('Сообщество','clubId',clubs.map(c=>[c.id,c.name]),state.campusEventClub||clubs[0]?.id)}${campusField('Название','title',event.title||'','text','required maxlength="140"')}<div class="field"><label for="campus-event-body">Описание</label><textarea id="campus-event-body" name="body" maxlength="3000" required>${esc(event.body||'')}</textarea></div><div class="ext-form-grid">${campusField('Начало, МСК','startsAt',campusLocalTime(event.startsAt)||day+'T18:00','datetime-local','required')}${campusField('Окончание, МСК','endsAt',campusLocalTime(event.endsAt)||day+'T19:30','datetime-local','required')}</div>${campusField('Где встречаемся','place',event.place||'Студенческий центр · зал 201','text','required maxlength="120"')}<div class="ext-form-grid">${campusField('Количество мест','capacity',event.capacity||20,'number','min="1" max="500" required')}${campusSelect('Кто может участвовать','audience',[['all','Все пользователи'],['members','Только участники клуба']],event.audience||'all')}</div><fieldset class="campus-cover-picker"><legend>Обложка события</legend>${[['orbit','Орбиты'],['studio','Студия'],['nature','Природа'],['sport','Движение']].map(([id,label])=>`<label><input type="radio" name="cover" value="${id}" ${(event.cover||'orbit')===id?'checked':''}>${campusEventCover({cover:id},true)}<span>${label}</span></label>`).join('')}</fieldset>${extModalActions(event.id?'Сохранить событие':'Опубликовать событие')}</form>`,'Афиша кампуса');
 }
 if(modal.type==='campus-event'){const e=modal.event;return extModalShell(e.title,e.club,`${campusEventCover(e)}<div class="campus-event-detail"><p>${esc(e.body)}</p><div>${icon('calendar')} ${esc(dateFmt(e.startsAt,{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Moscow'}))} — ${esc(campusTime(e.endsAt))}</div><div>${campusRoomButton(e.place)}</div><p>${e.participants} из ${e.capacity} мест занято · ${e.audience==='members'?'для участников клуба':'открытая встреча'}</p><div class="campus-action-stack">${e.status==='published'&&Date.parse(e.startsAt)>Date.now()?(e.isGoing?`<button class="btn btn-light" data-campus-event-leave="${esc(e.id)}">${icon('check')} Вы идёте · отменить участие</button>`:`<button class="btn btn-primary" data-campus-event-join="${esc(e.id)}" ${!e.remaining?'disabled':''}>Пойду ${icon('arrow')}</button>`):''}${e.canManage?`<button class="btn btn-light" data-campus-event-members="${esc(e.id)}">${icon('users')} Участники</button><button class="btn btn-ghost" data-campus-event-cancel="${esc(e.id)}" ${e.status==='cancelled'?'disabled':''}>Отменить событие</button>`:''}<button class="btn btn-light" data-campus-club-open="${esc(e.clubId)}">Перейти в сообщество</button></div></div>`,'Событие клуба');}
 if(modal.type==='campus-members')return extModalShell('Участники события','Список доступен только команде этого клуба.',`<div class="campus-members-list">${arr(modal.members).map(m=>`<div><span class="avatar">${esc(initials(m.name))}</span><span><strong>${esc(m.name)}</strong><small>${esc(m.tag||'Участник')}</small></span></div>`).join('')||emptyState('Пока никто не записался','Записи появятся после выбора «Пойду».','users')}</div>`,'Организатору');
 if(modal.type==='campus-slot'){const data=campusConsultData(),day=dateAdd(campusToday(),2);return extModalShell('Открыть время приёма','Один слот — одна индивидуальная встреча. Занятия и другие консультации проверяются автоматически.',`<form id="campus-slot-form"><div class="ext-form-grid">${campusField('Начало, МСК','startsAt',day+'T16:00','datetime-local','required')}${campusField('Окончание, МСК','endsAt',day+'T16:30','datetime-local','required')}</div>${campusSelect('Для кого','groupId',[['','Все учебные группы'],...arr(data.groups).map(g=>[g.id,g.name])])}${campusSelect('Формат','format',[['offline','В кампусе'],['online','Онлайн']])}${campusField('Аудитория или ссылка встречи','place','','text','required maxlength="160"')}${extModalActions('Открыть запись')}</form>`,'Консультации');}
 if(modal.type==='campus-book'){const s=modal.slot;return extModalShell('Записаться на консультацию',s.owner,`<form id="campus-book-form"><div class="campus-book-summary"><strong>${esc(shortDate(s.startsAt))} · ${esc(campusTime(s.startsAt))}–${esc(campusTime(s.endsAt))}</strong><span>${esc(s.place)}</span></div><div class="field"><label for="campus-book-topic">Что хотите обсудить?</label><textarea id="campus-book-topic" name="topic" required maxlength="400" placeholder="Например, вопросы по итоговому проекту"></textarea></div>${extModalActions('Подтвердить запись')}</form>`,'Время для разговора');}
 if(modal.type==='campus-forecast'){const {data,key,groupId,subject,rule}=campusForecastSelection(),choices=arr(data.options).map(o=>[campusRuleKey(o.groupId,o.subject),o.subject+' · '+(arr(data.groups).find(g=>g.id===o.groupId)?.name||o.groupId)]);return extModalShell(isStudent()?'Что будет, если…':'Правила прогноза','Расчёт показывает средневзвешенный балл; оценки журнала остаются прежними.',`${campusSelect('Дисциплина','forecast-choice',choices,key)}${data.canManage?`<form id="campus-grading-form">${campusField('Вес среднего текущих оценок, %','currentWeight',rule?.currentWeight||70,'number','required min="5" max="95"')}<p class="campus-footnote">Остальная доля относится к одной будущей итоговой работе. Текущие зачёты в среднее не входят.</p><div class="field"><label for="campus-grading-note">Пояснение студентам</label><textarea id="campus-grading-note" name="note" maxlength="600">${esc(rule?.note||'')}</textarea></div>${extModalActions('Сохранить правило')}</form>`:`${rule?`<div class="campus-rule-note"><strong>Текущие оценки ${rule.currentWeight}% · будущая работа ${rule.futureWeight}%</strong><p>${esc(rule.note||'')}</p><small>Опубликовал: ${esc(rule.author||'Преподаватель')}</small></div><label class="campus-range-label" for="campus-forecast-value">Результат будущей работы <strong id="campus-forecast-value-label">${Number(modal.forecastValue||4).toFixed(1)}</strong></label><input id="campus-forecast-value" class="campus-range" type="range" min="2" max="5" step="0.1" value="${Number(modal.forecastValue||4)}">${campusSelect('Цель: средневзвешенный балл','forecast-target',[['3','3,0'],['4','4,0'],['4.5','4,5'],['5','5,0']],String(modal.forecastTarget||4.5))}`:''}<div id="campus-forecast-result">${campusForecastResult()}</div><p class="campus-footnote">Это личный сценарий по опубликованным весам, а не новая оценка. Итоговое оценивание ведёт преподаватель.</p>`}`,'Успеваемость');}
 if(modal.type==='campus-place'){const data=state.data.campusMap||{},place=modal.place||{};return extModalShell('Место на схеме','Редактирование справочника вымышленного кампуса.',`<form id="campus-place-form">${campusField('Обозначение в расписании','room',place.room||state.campusPlace||'','text','required maxlength="120"')}${campusField('Название','title',place.title||'','text','required maxlength="140"')}<div class="ext-form-grid">${campusSelect('Корпус','building',arr(data.buildings).map(b=>[b.id,b.name]),place.building||'A')}${campusField('Этаж','floor',place.floor||1,'number','min="1" max="6" required')}</div><div class="field"><label for="campus-directions">Как пройти</label><textarea id="campus-directions" name="directions" required maxlength="600">${esc(place.directions||'')}</textarea></div>${extModalActions('Сохранить место')}</form>`,'Навигатор');}
 return '';
}

function campusClubEventPanel(){const club=state.data.clubDetail?.club,events=arr(campusEventsData().events).filter(e=>e.clubId===club?.id&&Date.parse(e.endsAt)>Date.now()).slice(0,2);return `<section class="campus-club-events"><div class="section-title"><h2>Встречаемся в клубе</h2><button class="text-link" data-campus-club-events="${esc(club?.id||'')}">Вся афиша →</button></div>${events.length?`<div class="campus-events-grid">${events.map(campusEventCard).join('')}</div>`:`<div class="card card-pad"><p class="muted">Ближайшие события ещё не объявлены.</p></div>`}</section>`;}
async function campusRefresh(){const keys=[...viewDataKeys(state.view),'campusOverview'];for(const k of ['campusEvents','campusConsultations'])if(state.data[k])keys.push(k);await loadData(keys);}
function campusConfirm(title,description,path,method='POST',note=''){state.modal={type:'campus-confirm',title,description,path,method,note};render();}
async function campusOpenSubject(subject,group){if(state.view!=='subject')state.campusReturn=currentRoute();state.campusSubject=subject;state.campusGroup=group||state.user.groupId||'';await navigateView('subject/'+encodeURIComponent(state.campusGroup)+'/'+encodeURIComponent(subject));}
async function campusOpenForecast(){const forecast=await api('/api/campus/forecast'),preferred=arr(forecast.options).find(x=>x.subject===state.campusSubject&&x.groupId===state.campusGroup)||arr(forecast.options)[0];state.modal={type:'campus-forecast',forecast,ruleKey:preferred?campusRuleKey(preferred.groupId,preferred.subject):'',forecastValue:4,forecastTarget:4.5};render();}
function campusCapturePreferences(){const form=root.querySelector('#campus-preferences-form');if(form&&state.modal?.type==='campus-preferences'){state.modal.selected=[...form.querySelectorAll('[name="widgets"]:checked')].map(x=>x.value);state.modal.preferences.compact=Boolean(form.elements.compact.checked);}}
function campusMoveWidget(from,to){if(state.modal?.type!=='campus-preferences'||to<0||to>=state.modal.order.length)return;campusCapturePreferences();const [item]=state.modal.order.splice(from,1);state.modal.order.splice(to,0,item);render();}
async function campusClick(event){
 if(!state.user)return false;const target=event.target;
 try{
  const lessonDate=target.closest('[data-campus-lesson-date]');if(lessonDate){state.teacherId='';state.scheduleMode='day';await selectScheduleDate(lessonDate.dataset.campusLessonDate);return true;}
  const subject=target.closest('[data-campus-subject]');if(subject){await campusOpenSubject(subject.dataset.campusSubject,subject.dataset.campusGroup);return true;}
  const place=target.closest('[data-campus-place]');if(place){state.campusPlace=place.dataset.campusPlace;state.campusMapSearch='';state.campusBuilding='';await navigateView('campus');return true;}
  const action=target.closest('[data-campus-action]');if(action){
   if(action.dataset.campusAction==='new-task'){state.modal={type:'campus-task'};render();}
   if(action.dataset.campusAction==='preferences'){const preferences=await api('/api/campus/preferences');state.modal={type:'campus-preferences',preferences,selected:[...preferences.widgets],order:[...preferences.widgets,...preferences.allowed.filter(x=>!preferences.widgets.includes(x))]};render();}
   if(action.dataset.campusAction==='forecast')await campusOpenForecast();
   if(action.dataset.campusAction==='subject-back')await navigateView(state.campusReturn||'schedule');
   if(action.dataset.campusAction==='new-event'){state.modal={type:'campus-event-form'};render();}
   if(action.dataset.campusAction==='new-slot'){state.modal={type:'campus-slot'};render();}
   if(['edit-place','new-place'].includes(action.dataset.campusAction)){state.modal={type:'campus-place',place:action.dataset.campusAction==='edit-place'?arr(state.data.campusMap?.places).find(x=>x.room===state.campusPlace):null};render();}return true;
  }
  const filter=target.closest('[data-campus-plan-filter]');if(filter){state.campusPlanFilter=filter.dataset.campusPlanFilter;render();return true;}
  const planOpen=target.closest('[data-campus-plan-open]');if(planOpen){const item=arr(campusPlanData().items).find(x=>x.key===planOpen.dataset.campusPlanOpen);if(!item)return true;if(item.kind==='task'){state.modal={type:'campus-task',task:item};render();}else if(item.kind==='homework'){state.homeworkDate=item.lessonDate;state.homeworkSubject=item.subject;state.homeworkGroup=item.groupId;await navigateView('homework');}else if(item.kind==='event'){await loadData(['campusEvents']);const e=arr(campusEventsData().events).find(x=>item.key==='event:'+x.id);if(e){state.modal={type:'campus-event',event:e};render();}}else await navigateView(({exam:'grades',news:'news',consultation:'consultations'}[item.kind])||'plan');return true;}
  const taskRemove=target.closest('[data-campus-task-remove]');if(taskRemove){campusConfirm('Удалить личную задачу?','Запись исчезнет только из вашего плана.','/api/campus/tasks/'+encodeURIComponent(taskRemove.dataset.campusTaskRemove),'DELETE','Учебное задание преподавателя этим действием не удаляется.');return true;}
  const eventFilter=target.closest('[data-campus-event-filter]');if(eventFilter){state.campusEventFilter=eventFilter.dataset.campusEventFilter;render();return true;}
  const clubEvents=target.closest('[data-campus-club-events]');if(clubEvents){state.campusEventClub=clubEvents.dataset.campusClubEvents;state.campusEventFilter='all';state.campusEventDate='';await navigateView('events');return true;}
  const eventButton=target.closest('[data-campus-event],[data-campus-event-edit],[data-campus-event-join],[data-campus-event-leave],[data-campus-event-members],[data-campus-event-cancel]');
  if(eventButton){
   const d=eventButton.dataset,id=d.campusEvent||d.campusEventEdit||d.campusEventJoin||d.campusEventLeave||d.campusEventMembers||d.campusEventCancel,e=arr(campusEventsData().events).find(x=>x.id===id);if(!e)return true;
   if(d.campusEvent){state.modal={type:'campus-event',event:e};render();}
   if(d.campusEventEdit){state.modal={type:'campus-event-form',event:e};render();}
   if(d.campusEventJoin){eventButton.disabled=true;await api('/api/campus/events/'+encodeURIComponent(id)+'/join','POST',{});await campusRefresh();if(state.modal?.type==='campus-event'&&state.modal.event.id===id)state.modal.event=arr(campusEventsData().events).find(x=>x.id===id)||state.modal.event;render();toast('Вы в списке участников. Встреча добавлена в ваш план.');}
   if(d.campusEventLeave)campusConfirm('Отменить участие?','Место станет доступным другому участнику.','/api/campus/events/'+encodeURIComponent(id)+'/leave','POST','Вы сможете записаться снова, если останутся свободные места.');
   if(d.campusEventCancel)campusConfirm('Отменить событие клуба?','Записанные участники увидят уведомление.','/api/campus/events/'+encodeURIComponent(id)+'/cancel','POST','Событие сохранится с отметкой об отмене.');
   if(d.campusEventMembers){const result=await api('/api/campus/events/'+encodeURIComponent(id)+'/members');state.modal={type:'campus-members',members:result.members};render();}return true;
  }
  const consultStaff=target.closest('[data-campus-consult-staff]');if(consultStaff){state.campusConsultStaff=consultStaff.dataset.campusConsultStaff;state.campusConsultFilter='all';await navigateView('consultations');return true;}
  const consultFilter=target.closest('[data-campus-consult-filter]');if(consultFilter){state.campusConsultFilter=consultFilter.dataset.campusConsultFilter;render();return true;}
  const book=target.closest('[data-campus-book]');if(book){const slot=arr(campusConsultData().slots).find(x=>x.id===book.dataset.campusBook);if(slot){state.modal={type:'campus-book',slot};render();}return true;}
  const bookingCancel=target.closest('[data-campus-booking-cancel]');if(bookingCancel){campusConfirm('Отменить запись?','Свободное окно снова станет доступно студентам.','/api/campus/bookings/'+encodeURIComponent(bookingCancel.dataset.campusBookingCancel)+'/cancel');return true;}
  const slotCancel=target.closest('[data-campus-slot-cancel]');if(slotCancel){campusConfirm('Закрыть время приёма?','Если студент уже записан, его запись отменится с уведомлением.','/api/campus/slots/'+encodeURIComponent(slotCancel.dataset.campusSlotCancel)+'/cancel');return true;}
  const building=target.closest('[data-campus-building]');if(building){state.campusBuilding=building.dataset.campusBuilding;if(state.campusBuilding&&arr(state.data.campusMap?.places).find(p=>p.room===state.campusPlace)?.building!==state.campusBuilding)state.campusPlace='';render();return true;}
  const mapRoom=target.closest('[data-campus-map-room]');if(mapRoom){state.campusPlace=mapRoom.dataset.campusMapRoom;render();root.querySelector('#campus-map-detail')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});return true;}
  const move=target.closest('[data-campus-widget-move]');if(move){campusMoveWidget(Number(move.dataset.campusWidgetMove),Number(move.dataset.campusWidgetMove)+Number(move.dataset.direction));return true;}
  if(target.closest('[data-campus-hub-homework]')){state.homeworkSubject=state.campusSubject;state.homeworkDate=campusToday();state.homeworkGroup=state.campusGroup;await navigateView('homework');return true;}
  if(target.closest('[data-campus-hub-materials]')){state.resourceSubject=state.campusSubject;state.resourceKind='all';state.resourceAuthor='';await navigateView('resources');return true;}
  const resource=target.closest('[data-campus-hub-resource]');if(resource){const data=await api('/api/resources');state.data.resources=normalized.resources(data);state.modal={type:'resource',id:resource.dataset.campusHubResource};render();return true;}
  const club=target.closest('[data-campus-club-open]');if(club){await navigateView('club/'+encodeURIComponent(club.dataset.campusClubOpen));return true;}
 }catch(error){toast(error.message||'Не удалось выполнить действие.',true);if(target.closest('[data-campus-event-join]')){await campusRefresh();render();}return true;}
 return false;
}
async function campusChange(event){const el=event.target;if(!state.user)return false;try{
 if(el.dataset.campusProgress){el.disabled=true;await api('/api/campus/progress','PATCH',{key:el.dataset.campusProgress,status:el.value});await campusRefresh();render();return true;}
 const fields={'campus-plan-subject':'campusPlanSubject','campus-event-club':'campusEventClub','campus-event-date':'campusEventDate','campus-consult-staff':'campusConsultStaff'};if(fields[el.id]){state[fields[el.id]]=el.value;render();return true;}
 if(el.id==='campus-forecast-choice'){state.modal.ruleKey=el.value;render();return true;}
 if(el.id==='campus-forecast-target'){state.modal.forecastTarget=Number(el.value);const output=root.querySelector('#campus-forecast-result');if(output)output.innerHTML=campusForecastResult();return true;}
 }catch(error){toast(error.message,true);await campusRefresh();render();return true;}return false;}
async function campusSubmit(form,values){
 if(!form.id.startsWith('campus-'))return false;
 if(form.id==='campus-task-form'){await api('/api/campus/tasks'+(state.modal.task?'/'+encodeURIComponent(state.modal.task.id):''),state.modal.task?'PATCH':'POST',{title:values.title,subject:values.subject,dueDate:values.dueDate});toast('Личная задача сохранена.');}
 if(form.id==='campus-confirm-form'){await api(state.modal.path,state.modal.method,{});toast('Изменение сохранено.');}
 if(form.id==='campus-preferences-form'){const widgets=state.modal.order.filter(id=>form.querySelector('[name="widgets"][value="'+id+'"]')?.checked);if(!widgets.length)throw new Error('Оставьте хотя бы одну карточку на главной.');await api('/api/campus/preferences','PUT',{widgets,compact:Boolean(form.elements.compact.checked)});toast('Ваша главная обновлена.');}
 if(form.id==='campus-event-form'){const e=state.modal.event;await api('/api/campus/events'+(e?'/'+encodeURIComponent(e.id):''),e?'PATCH':'POST',{...values,capacity:Number(values.capacity)});toast(e?'Событие обновлено.':'Событие появилось в афише.');}
 if(form.id==='campus-slot-form'){await api('/api/campus/slots','POST',values);toast('Окно приёма открыто.');}
 if(form.id==='campus-book-form'){await api('/api/campus/slots/'+encodeURIComponent(state.modal.slot.id)+'/book','POST',{topic:values.topic});toast('Вы записаны. Встреча появилась в вашем плане.');}
 if(form.id==='campus-grading-form'){const {groupId,subject}=campusForecastSelection();await api('/api/campus/grading','PUT',{groupId,subject,currentWeight:Number(values.currentWeight),note:values.note});toast('Правило опубликовано для группы.');}
 if(form.id==='campus-place-form'){await api('/api/campus/places','PUT',{...values,floor:Number(values.floor)});state.campusPlace=values.room;await loadData(['campusMap']);toast('Место сохранено на схеме.');}
 await campusRefresh();return true;
}
root.addEventListener('input',event=>{
 if(event.target.id==='campus-map-search'){state.campusMapSearch=event.target.value;const results=root.querySelector('#campus-map-results');if(results)results.innerHTML=campusMapResults();}
 if(event.target.id==='campus-forecast-value'&&state.modal?.type==='campus-forecast'){state.modal.forecastValue=Number(event.target.value);const label=root.querySelector('#campus-forecast-value-label'),result=root.querySelector('#campus-forecast-result');if(label)label.textContent=Number(event.target.value).toFixed(1);if(result)result.innerHTML=campusForecastResult();}
});
root.addEventListener('dragstart',event=>{const row=event.target.closest('[data-campus-widget-drag]');if(row&&state.modal?.type==='campus-preferences'){state.modal.dragIndex=Number(row.dataset.campusWidgetDrag);event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',row.dataset.campusWidgetDrag);}});
root.addEventListener('dragover',event=>{if(event.target.closest('[data-campus-widget-drag]')&&state.modal?.type==='campus-preferences')event.preventDefault();});
root.addEventListener('drop',event=>{const row=event.target.closest('[data-campus-widget-drag]');if(row&&state.modal?.type==='campus-preferences'){event.preventDefault();campusMoveWidget(state.modal.dragIndex,Number(row.dataset.campusWidgetDrag));}});
extGuideSections.push(
 {id:'campus-plan',name:'План и предметы',title:'От срока — к нужному действию',intro:'Личный план объединяет учебные даты и задачи самого пользователя. Страница предмета связывает существующие разделы.',steps:[['Откройте личный план','Выберите сегодня, ближайшие семь дней, просроченное или готовое. Предмет помогает отфильтровать задачи. Личная задача видна только её автору.'],['Различайте отметку и результат','«Готово» — личный прогресс пользователя, а не принятие работы преподавателем. Оценки в журнале этим действием не меняются.'],['Откройте название предмета','Из расписания или плана перейдите к заданиям, общим и авторским материалам, преподавателям и собственным результатам. Кнопка «Назад» возвращает исходный учебный контекст.']]},
 {id:'campus-events',name:'Мероприятия клубов',title:'От идеи встречи до списка участников',intro:'Публиковать и отменять мероприятия могут администрация и команда соответствующего клуба.',steps:[['Создайте событие','В афише выберите «Создать событие»: укажите клуб, начало и конец по Москве, место, число участников, аудиторию и обложку.'],['Проверьте аудиторию','Открытое событие доступно вошедшим пользователям. Закрытое — участникам клуба. После появления записей аудиторию менять нельзя. Число мест нельзя уменьшить ниже числа участников.'],['Работайте с записью','Студент выбирает «Пойду», организатор открывает «Подробнее → Участники». Отмена участия освобождает место. При отмене события записанные люди получают уведомление. Выход из клуба отменяет запись на его закрытые события.']]},
 {id:'campus-consultations',name:'Приём и консультации',title:'Свободное время без переписки о каждом слоте',intro:'Преподаватель и сотрудник учебного офиса открывают индивидуальные окна приёма; студент выбирает подходящее.',steps:[['Откройте время приёма','В консультациях укажите начало, конец, формат, аудиторию или описание онлайн-встречи. При необходимости ограничьте запись учебной группой. Один слот предназначен для одного студента.'],['Учитывайте расписание','Система проверяет занятия сотрудника и студента, пересечения слотов и других записей студента. Если время уже заняли, выберите другое. Время отображается по Москве.'],['Соблюдайте приватность','Тему и имя записанного студента видят сам студент, владелец приёма и администрация. Другие посетители видят только занятость. Отмените запись или закройте приём; отмена появится в уведомлениях.']]},
 {id:'campus-personal',name:'Прогноз, главная, карта',title:'Личные инструменты и справочник кампуса',intro:'Настройки главной и прогнозы принадлежат конкретному пользователю, справочник мест поддерживает администрация.',steps:[['Опубликуйте правило прогноза','Откройте свой предмет и «Правила оценивания». Задайте вес среднего текущих оценок; оставшийся вес относится к одной будущей работе. Поясните условия. Студент сможет менять ожидаемый результат только в личном расчёте.'],['Настройте главную','Выберите нужные карточки, переставьте мышью либо кнопками вверх/вниз, включите компактный режим. Порядок сохраняется в аккаунте. Срочные изменения расписания остаются видны над карточками.'],['Поддерживайте схему','Нажатие на аудиторию открывает кампус. Администрация может добавить место: обозначение должно совпадать с расписанием, затем выбираются корпус, этаж и текстовый путь. Схема вымышленная и не является масштабным планом реального здания.']]}
);

function campusOnlinePlace(value){try{const url=new URL(value);if(url.protocol==='https:')return `<a class="campus-inline-link" href="${esc(url.href)}" target="_blank" rel="noopener noreferrer">${icon('external','icon-sm')} Открыть онлайн-встречу</a>`;}catch{}return esc(value);}
